inline const BoardPresetInfo *findBoardPreset(const char *id) {
  if(!id)return nullptr;
  for(size_t i=0;i<BoardPresetCount;++i){const auto *p=boardPresetAt(i);if(strcmp(p->id,id)==0)return p;}
  return nullptr;
}
